class GoldenDUT:
    def __init__(self):
        # Initialize flip-flops to zero
        self.ff_xor_reg = 0
        self.ff_and_reg = 0
        self.ff_or_reg = 0

    def load(self, signal_vector):
        # Extract input signal x from signal_vector
        x = signal_vector['x']

        # Update the state of the flip-flops based on the given logic
        # The operation is done in such a way that it reflects a sequential process
        xor_input = x ^ self.ff_xor_reg
        and_input = x & (~self.ff_and_reg & 1)
        or_input = x | (~self.ff_or_reg & 1)

        # Update registers for the next state
        # Corrected: ensure this reflects the intended feedback logic from Verilog
        self.ff_xor_reg = xor_input
        self.ff_and_reg = and_input
        self.ff_or_reg = or_input

    def check(self, signal_vector):
        # Calculate expected output based on the updated registers
        # Corrected: Ensure XNOR operation is accurately depicted
        expected_z = ~(self.ff_xor_reg ^ self.ff_and_reg ^ self.ff_or_reg) & 1
        observed_z = signal_vector['z']

        # Check if the expected output matches the observed output
        if expected_z == observed_z:
            return True
        else:
            print(f"Scenario: {signal_vector['scenario']}, expected: z={expected_z}, observed z={observed_z}")
            return False
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

