        # Initialize the inner states (flip-flop outputs)
        self.dff1_reg = 0
        self.dff2_reg = 0
        self.dff3_reg = 0
        self.z_reg = 0

    def load(self, signal_vector):
        # Input signals
        x = signal_vector['x']

        # Processing the logic gates linked to flip-flops
        # Ensure the flip-flops are updated with correct operations
        xor_result = x ^ self.dff1_reg  # XOR with current flip-flop state
        and_result = x & (~self.dff2_reg & 0b1)  # AND with complemented current flip-flop state
        or_result = x | (~self.dff3_reg & 0b1)  # OR with complemented current flip-flop state

        # Update the flip-flops to the next state
        self.dff1_reg = xor_result
        self.dff2_reg = and_result
        self.dff3_reg = or_result

        # Calculate current output at the XNOR gate, ensuring proper logic
        self.z_reg = ~(self.dff1_reg ^ self.dff2_reg ^ self.dff3_reg) & 0b1

    def check(self, signal_vector):
        # Output signals from DUT to be verified
        z_observed = signal_vector['z']

        # If it's time to check, compare the expected and observed output
        if signal_vector['check_en']:
            if self.z_reg != z_observed:
                print(f"Scenario: {signal_vector['scenario']}, expected: z={self.z_reg}, observed: z={z_observed}")
