class GoldenDUT:
    def __init__(self):
        # Initialize flip-flop states to zero as per the given specifications
        self.Q_xor_reg = 0
        self.Q_and_reg = 0
        self.Q_or_reg = 0

    def load(self, signal_vector):
        x = signal_vector['x']

        # XOR gate logic: Flip-flop is toggled using XOR with its current state
        D_xor = x ^ self.Q_xor_reg

        # AND gate logic: ANDing input x with complemented current state
        D_and = x & (~self.Q_and_reg & 0b1)

        # OR gate logic: ORing input x with complemented current state
        D_or = x | (~self.Q_or_reg & 0b1)

        # Update the states of the flip-flops
        self.Q_xor_reg = D_xor
        self.Q_and_reg = D_and
        self.Q_or_reg = D_or

    def check(self, signal_vector):
        # Calculate expected output 'z'
        expected_z = ~(self.Q_xor_reg ^ self.Q_and_reg ^ self.Q_or_reg) & 0b1

        # Observed 'z' from signal vector
        observed_z = signal_vector['z']

        # Compare expected and observed z
        if expected_z == observed_z:
            return True
        else:
            print(f"Scenario: {signal_vector['scenario']}, expected: z={expected_z}, observed: z={observed_z}")
            return False

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
