        # Initialize internal states of the D flip-flops to 0
        self.xor_reg = 0
        self.and_reg = 0
        self.or_reg = 0

    def xor_ff(self, x, ff_output):
        """Logic for XOR gate connected to a D flip-flop."""
        return x ^ ff_output

    def and_ff(self, x, ff_output):
        """Logic for AND gate connected to a D flip-flop, using complemented FF output."""
        # Assuming a correct interpretation: AND gate should use (ff_output & x)
        return x & ff_output

    def or_ff(self, x, ff_output):
        """Logic for OR gate connected to a D flip-flop, using complemented FF output."""
        # Assuming a correct interpretation: OR gate should use (ff_output | x)
        return x | ff_output

    def xnor3(self, a, b, c):
        """3-input XNOR gate."""
        return ~(a ^ b ^ c) & 0b1  # Mask to ensure output is a single bit

    def load(self, signal_vector):
        # Load input signal
        x = signal_vector['x']

        # Calculate next states for the flip-flops based on current inputs and states
        new_xor_reg = self.xor_ff(x, self.xor_reg)
        new_and_reg = self.and_ff(x, ~self.and_reg & 0b1)  # Complement correctly
        new_or_reg = self.or_ff(x, ~self.or_reg & 0b1)     # Complement correctly

        # Update internal D flip-flop states
        self.xor_reg = new_xor_reg
        self.and_reg = new_and_reg
        self.or_reg = new_or_reg

