class GoldenDUT:
    def __init__(self):
        self.previous_in_reg = 0
        self.out_reg = 0

    def load(self, signal_vector):
        if signal_vector['reset'] == 1:
            self.out_reg = 0
        else:
            current_in = signal_vector['in']
            self.out_reg |= self.detect_transitions(self.previous_in_reg, current_in)
            # Update the previous input register after detecting transitions
            self.previous_in_reg = current_in

    def check(self, signal_vector):
        expected_out = self.out_reg
        observed_out = signal_vector['out']
        if expected_out != observed_out:
            print(f"Scenario: {signal_vector['scenario']}, expected: out={expected_out:032b}, observed out={observed_out:032b}")
            return False
        return True

    def detect_transitions(self, previous_in, current_in):
        detected_transitions = 0
        for i in range(32):
            # Correctly detect 1->0 transitions
            if (previous_in & (1 << i)) and not (current_in & (1 << i)):
                detected_transitions |= (1 << i)
        return detected_transitions
