    def __init__(self):
        self.previous_in_reg = 0  # 32-bit register for input
        self.out_reg = 0  # 32-bit output register

    def load(self, signal_vector):
        if signal_vector['reset']:
            self.out_reg = 0
            # Reset the previous input register to avoid incorrect falling edge detection
            self.previous_in_reg = 0
        else:
            current_in = signal_vector['in']
            self.out_reg |= self.calculate_falling_edges(self.previous_in_reg, current_in)
            self.previous_in_reg = current_in

    def check(self, signal_vector):
        if not signal_vector['check_en']:
            return True
        expected_out = self.out_reg & 0xFFFFFFFF  # Ensure 32-bit mask
        observed_out = signal_vector['out']
        if expected_out != observed_out:
            print(f"Scenario: {signal_vector['scenario']}, expected: out={expected_out}, observed out={observed_out}")
            return False
        return True

    def calculate_falling_edges(self, previous_input, current_input):
        # Convert inputs to binary arrays
        previous_bits = np.array([int(bit) for bit in format(previous_input, '032b')], dtype=int)
        current_bits = np.array([int(bit) for bit in format(current_input, '032b')], dtype=int)

        # Calculate falling edges
        falling_edges = np.bitwise_and(previous_bits == 1, current_bits == 0)

        # Convert the boolean array of falling edges to integer
        return int(''.join(falling_edges.astype(int).astype(str)), 2)
