        # Load the input signals and update the inner state
        areset = signal_vector['areset']
        train_valid = signal_vector['train_valid']
        train_taken = signal_vector['train_taken']

        # Update state based on areset and train_valid/train_taken signals
        if areset:
            # Reset to weakly not-taken (0b01)
            self.state_reg = 0b01
        elif train_valid:
            if train_taken:
                # Incrementing the counter with saturation at 3
                self.state_reg = min(self.state_reg + 1, 0b11)
            else:
                # Decrementing the counter with saturation at 0
                self.state_reg = max(self.state_reg - 1, 0b00)

        # Ensure state_reg fits within 2 bits
        self.state_reg &= 0b11

    def check(self, signal_vector):
        # Obtain the observed state from the DUT
        state_observed = signal_vector['state']

        # Compare the observed state with the expected state
        if self.state_reg != state_observed:
            print(f"Scenario: {signal_vector['scenario']}, expected: state={self.state_reg}, observed: state={state_observed}")
            return False
        return True

