        elif current_state == self.STATE_C:
            if r2:
                next_state = self.STATE_C
                g2 = 1
            else:
                next_state = self.STATE_A

        elif current_state == self.STATE_D:
            next_state = self.STATE_A

        return next_state, g1, g2, g3

