class GoldenDUT:
    # State encoding
    STATE_A = 0b00
    STATE_B = 0b01
    STATE_C = 0b10
    STATE_D = 0b11

    def __init__(self):
        # Initialize internal state and output grants
        self.state_reg = self.STATE_A
        self.g_reg = 0b000

    def load(self, signal_vector):
        # If resetn is low (active low reset), go to STATE_A
        if signal_vector['resetn'] == 0:
            self.state_reg = self.STATE_A
            self.g_reg = 0b000
        else:
            # Process request vector 'r'
            r = signal_vector['r']
            r1 = (r >> 2) & 1
            r2 = (r >> 1) & 1
            r3 = r & 1

            # Determine next state based on current state and input 'r'
            self.state_reg = self.get_next_state(self.state_reg, r1, r2, r3)
            # Update the grants based on state
            self.g_reg = self.get_grants(self.state_reg)

    def check(self, signal_vector):
        # Check the output 'g' values
        g_observed = signal_vector['g']
        g_expected = self.g_reg

        if g_observed != g_expected:
            print(f"Scenario: {signal_vector['scenario']}, expected: g={bin(g_expected)}, observed g={bin(g_observed)}")
            return False
        return True

    def get_next_state(self, current_state, r1, r2, r3):
        # FSM transitions based on current state and inputs with the priority: r1 > r2 > r3
        if current_state == self.STATE_A:
            # Priority: r1 > r2 > r3
            if r1 == 1:
                return self.STATE_B
            elif r2 == 1:
                return self.STATE_C
            elif r3 == 1:
                return self.STATE_D
            return self.STATE_A  # If no requests, stay in STATE_A

        elif current_state == self.STATE_B:
            if r1 == 1:
                return self.STATE_B
            return self.STATE_A

        elif current_state == self.STATE_C:
            if r2 == 1:
                return self.STATE_C
            return self.STATE_A

        elif current_state == self.STATE_D:
            return self.STATE_A  # Revert to STATE_A if all requests are cleared

    def get_grants(self, state):
        # Output grants based on current state
        if state == self.STATE_A:
            return 0b000
        elif state == self.STATE_B:
            return 0b100
        elif state == self.STATE_C:
            return 0b010
        elif state == self.STATE_D:
            return 0b001
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
