class GoldenDUT:
    def __init__(self):
        self.state_reg = 0  # 0: waiting for start byte, 1: waiting for second byte, 2: waiting for third byte
        self.done_reg = 0   # State of the done signal

    def load(self, signal_vector):
        # Reset logic
        if signal_vector['reset']:
            self.state_reg = 0
            self.done_reg = 0
            return

        # FSM logic
        in_byte = signal_vector['in']

        if self.state_reg == 0:
            if in_byte & 0b00001000:  # Check in[3] for start byte
                self.state_reg = 1
            # Ensure done remains zero if no valid start byte is found
            self.done_reg = 0
        elif self.state_reg == 1:
            # Transition to state 2 on receipt of the second byte
            # unless overridden by a new valid start byte
            if in_byte & 0b00001000:  # In case another start byte appears
                self.state_reg = 1
            else:
                self.state_reg = 2
            self.done_reg = 0
        elif self.state_reg == 2:
            # If in the final state, only move back to the initial state
            # and assert done if the third byte is successfully processed
            self.state_reg = 0
            self.done_reg = 1

    def check(self, signal_vector):
        if signal_vector['check_en']:
            done_observed = signal_vector['done']
            if self.done_reg != done_observed:
                print(f"Scenario: {signal_vector['scenario']}, expected: done={self.done_reg}, observed done={done_observed}")
                return False
        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
