class GoldenDUT:
    def __init__(self):
        # Initialize internal state and done signal register
        self.state_reg = 0  # Corresponds to WAIT_FOR_START
        self.done_reg = 0

    def load(self, signal_vector):
        # Extract input signals from the signal vector
        in_signal = signal_vector['in']
        reset = signal_vector['reset']

        # State machine transitions based on current state and input
        if reset:
            # Reset FSM to WAIT_FOR_START state
            self.state_reg = 0
            self.done_reg = 0
        else:
            if self.state_reg == 0:  # WAIT_FOR_START
                if in_signal & 0b00001000:  # Check if in[3] is 1 to identify the start of message
                    self.state_reg = 1  # Transition to BYTE_1_RECEIVED
                    self.done_reg = 0
                else:
                    self.done_reg = 0
            elif self.state_reg == 1:  # BYTE_1_RECEIVED
                self.state_reg = 2  # Transition to BYTE_2_RECEIVED
                self.done_reg = 0
            elif self.state_reg == 2:  # BYTE_2_RECEIVED
                self.state_reg = 3  # Transition to BYTE_3_RECEIVED
                self.done_reg = 0
            elif self.state_reg == 3:  # BYTE_3_RECEIVED
                if in_signal & 0b00001000: # Check if in[3] = 1 to ensure correct synchronization
                    self.done_reg = 1  # Signal done for one cycle
                else:
                    self.done_reg = 0
                self.state_reg = 0  # Transition back to WAIT_FOR_START

    def check(self, signal_vector):
        # Check enable signal
        if not signal_vector['check_en']:
            return True

        # Extract output signal from DUT
        done_observed = signal_vector['done']

        # Determine expected output
        if self.done_reg == done_observed:
            return True
        else:
            scenario = signal_vector['scenario']
            print(f"Scenario: {scenario}, expected: done={self.done_reg}, observed done={done_observed}")
            return False
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
