class GoldenDUT:
    def __init__(self):
        self.a_reg = 0
        self.p_reg = 0
        self.q_reg = 0
        self.p_initialized = False
        self.previous_a = 0  # Track previous `a` value for transition detection

    def load(self, signal_vector):
        # Load the input signal
        self.previous_a = self.a_reg
        self.a_reg = signal_vector['a']

        # A new clock cycle begins; check for rising edge to update p and q
        if not self.p_initialized:
            self.p_reg = 0
            self.q_reg = 0
            self.p_initialized = True
        else:
            self.p_reg = self.a_reg  # `p` gets the value of `a` on the rising edge if initialized
            # Toggle `q` only if `a` transitions from 0 to 1
            if self.previous_a == 0 and self.a_reg == 1:
                self.q_reg = not self.q_reg

    def check(self, signal_vector):
        # This function is called when 'check_en' is True
        if signal_vector['check_en']:
            a_observed = signal_vector['a']
            p_observed = signal_vector['p']
            q_observed = signal_vector['q']

            # Compare expected outputs with observed outputs
            if self.p_reg != p_observed or self.q_reg != q_observed:
                print(f"Scenario: {signal_vector['scenario']}, "
                      f"expected: p={self.p_reg}, q={self.q_reg}, "
                      f"observed: p={p_observed}, q={q_observed}")
                return False

        return True

