class GoldenDUT:
    # Define the state encodings as constants
    STATE_A = 0b10  # One-hot encoded state A
    STATE_B = 0b01  # One-hot encoded state B

    def __init__(self):
        # Initialize the state to STATE_A (since reset goes to A)
        self.state_reg = GoldenDUT.STATE_A
        self.z_reg = 0  # Initial value of output z

    def load(self, signal_vector):
        # Apply asynchronous reset
        if signal_vector['areset'] == 1:
            self.state_reg = GoldenDUT.STATE_A
            self.z_reg = 0  # Reset output z as well
        else:
            # No reset, update state based on x
            x = signal_vector['x']
            self.state_reg, self.z_reg = self.mealy_machine_rules(self.state_reg, x)

    def check(self, signal_vector):
        # Compare the expected z and the observed z from signal vector
        z_observed = signal_vector['z']
        if self.z_reg != z_observed:
            # Output mismatch
            print(f"Scenario: {signal_vector['scenario']}, expected z={self.z_reg}, observed z={z_observed}")
            return False
        return True

    def mealy_machine_rules(self, state, x):
        """Core rules to determine the next state and output (z) based on current state and input x."""
        next_state = state
        z = 0  # Default output unless otherwise determined

        if state == GoldenDUT.STATE_A:
            if x == 0:
                next_state = GoldenDUT.STATE_A
                z = 0
            elif x == 1:
                next_state = GoldenDUT.STATE_B
                z = 1
        elif state == GoldenDUT.STATE_B:
            if x == 0:
                next_state = GoldenDUT.STATE_B
                z = 1
            elif x == 1:
                next_state = GoldenDUT.STATE_B
                z = 0

        return next_state, z
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

