class GoldenDUT:
    def __init__(self):
        # Initialize internal registers
        self.s_reg = 0
        self.previous_level_reg = "below_s1"
        self.fr3_reg = 0
        self.fr2_reg = 0
        self.fr1_reg = 0
        self.dfr_reg = 0

    def load(self, signal_vector):
        # Handle reset condition
        if signal_vector.get('reset', False):
            self.reset_registers()

        # Load sensor values
        self.s_reg = (signal_vector['s'] & 0b111)

        # Determine the current water level
        self.current_level = self.determine_water_level(self.s_reg)

        # Update internal registers based on the current level and previous level
        expected_outputs = self.determine_flow_rate(self.current_level, self.previous_level_reg)
        self.fr1_reg = expected_outputs['fr1']
        self.fr2_reg = expected_outputs['fr2']
        self.fr3_reg = expected_outputs['fr3']
        self.dfr_reg = expected_outputs['dfr']

        # Update previous level only when reset is not active
        if not signal_vector.get('reset', False):
            self.previous_level_reg = self.current_level

    def check(self, signal_vector):
        if signal_vector['check_en']:
            # Compare expected output with the DUT's output
            expected = (self.fr3_reg, self.fr2_reg, self.fr1_reg, self.dfr_reg)
            observed = (signal_vector['fr3'], signal_vector['fr2'], signal_vector['fr1'], signal_vector['dfr'])
            if expected != observed:
                print(f"Scenario: {signal_vector['scenario']}, expected: {expected}, observed: {observed}")
                return False
        return True

    def determine_water_level(self, sensor_input):
        s3, s2, s1 = (sensor_input >> 2) & 1, (sensor_input >> 1) & 1, sensor_input & 1
        if s3 and s2 and s1:
            return "above_s3"
        elif not s3 and s2 and s1:
            return "between_s3_and_s2"
        elif not s3 and not s2 and s1:
            return "between_s2_and_s1"
        else:
            return "below_s1"

    def determine_flow_rate(self, current_level, previous_level):
        expected_outputs = {
            'fr3': 0,
            'fr2': 0,
            'fr1': 0,
            'dfr': 0
        }

        if current_level == "above_s3":
            pass
        elif current_level == "between_s3_and_s2":
            expected_outputs['fr1'] = 1
        elif current_level == "between_s2_and_s1":
            expected_outputs['fr1'] = 1
            expected_outputs['fr2'] = 1
        elif current_level == "below_s1":
            expected_outputs['fr1'] = 1
            expected_outputs['fr2'] = 1
            expected_outputs['fr3'] = 1

        if self.transition_causes_dfr(previous_level, current_level):
            expected_outputs['dfr'] = 1

        return expected_outputs

    def reset_registers(self):
        self.s_reg = 0
        self.previous_level_reg = "below_s1"
        self.fr3_reg = 1
        self.fr2_reg = 1
        self.fr1_reg = 1
        self.dfr_reg = 1

    def transition_causes_dfr(self, previous_level, current_level):
        # Adjust logic to correctly reflect when dfr should be asserted
        return (
            (previous_level == "below_s1" and current_level in ["between_s2_and_s1", "between_s3_and_s2", "above_s3"]) or
            (previous_level == "between_s2_and_s1" and current_level in ["between_s3_and_s2", "above_s3"]) or
            (previous_level == "between_s3_and_s2" and current_level in ["above_s3"])
        )
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

