class GoldenDUT:
    def __init__(self):
        self.waiting_for_start_reg = True
        self.data_bits_collected_reg = 0
        self.byte_received_correctly_reg = False
        self.current_data_reg = 0

        # Constants
        self.START_BIT = 0
        self.STOP_BIT = 1
        self.DATA_BIT_COUNT = 8

    def load(self, signal_vector):
        # Reset indication handling
        if signal_vector['reset'] == 1:
            self.__init__()  # Reset state machine
            return

        in_bit = signal_vector['in']

        # FSM Logic
        if self.waiting_for_start_reg:
            if in_bit == self.START_BIT:
                self.waiting_for_start_reg = False
                self.data_bits_collected_reg = 0  # Reset data bit counter
                self.byte_received_correctly_reg = False  # Clear byte reception status
                self.current_data_reg = 0  # Reset the data accumulator
        elif self.data_bits_collected_reg < self.DATA_BIT_COUNT:
            # Shift in the new data bit on each cycle
            self.current_data_reg = (self.current_data_reg >> 1) | (in_bit << (self.DATA_BIT_COUNT - 1))
            self.data_bits_collected_reg += 1
        else:
            # Expecting stop bit
            if in_bit == self.STOP_BIT:
                self.byte_received_correctly_reg = True

            # Reset for the next byte
            self.waiting_for_start_reg = True
            self.data_bits_collected_reg = 0
            self.current_data_reg = 0

    def check(self, signal_vector):
        # If check is enabled, verify correctness
        if signal_vector.get('check_en', False):
            done_observed = signal_vector['done']
            done_expected = self.byte_received_correctly_reg

            if done_expected != done_observed:
                print(f"Scenario: {signal_vector['scenario']}, expected done={done_expected}, observed done={done_observed}")
                return False
        return True
