class GoldenDUT:
    def __init__(self):
        self.state_reg = 'IDLE'
        self.data_bits_reg = []
        self.done_reg = 0

    def load(self, signal_vector):
        in_signal = signal_vector['in']
        reset = signal_vector['reset']

        if reset:
            self.reset()
        else:
            self.update_state(in_signal)

    def reset(self):
        self.state_reg = 'IDLE'
        self.data_bits_reg = []
        self.done_reg = 0

    def update_state(self, in_signal):
        if self.state_reg == 'IDLE':
            if in_signal == 0:
                self.state_reg = 'START'

        elif self.state_reg == 'START':
            self.data_bits_reg = []
            self.state_reg = 'DATA'

        elif self.state_reg == 'DATA':
            self.data_bits_reg.append(in_signal)
            if len(self.data_bits_reg) == 8:
                self.state_reg = 'STOP'

        elif self.state_reg == 'STOP':
            self.done_reg = (in_signal == 1)
            self.state_reg = 'FIND_STOP'

        elif self.state_reg == 'FIND_STOP':
            if in_signal == 1:
                self.state_reg = 'IDLE'

        self.done_reg = 0 if self.state_reg != 'STOP' else self.done_reg

    def check(self, signal_vector):
        observed_done = signal_vector['done']
        if signal_vector['check_en']:
            if self.done_reg != observed_done:
                scenario = signal_vector['scenario']
                print(f"Scenario: {scenario}, expected: done={self.done_reg}, observed done={observed_done}")
                return False
        return True

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
