            self.ena_reg = 0
        else:
            self.q_reg, self.ena_reg = self.bcd_increment(self.q_reg)

    def check(self, signal_vector):
        # Compare expected output with actual DUT output
        expected_q = self.q_reg
        expected_ena = self.ena_reg

        observed_q = signal_vector['q']
        observed_ena = signal_vector.get('ena', 0)

        if expected_q != observed_q or expected_ena != observed_ena:
            print(f"Scenario: {signal_vector['scenario']}, expected: q={format(expected_q, '04X')}, ena={expected_ena}, observed: q={format(observed_q, '04X')}, ena={observed_ena}")
            return False
        return True

    def bcd_increment(self, q):
        # Increment a 4-digit BCD counter
        ones = (q & 0x000F)
        tens = (q & 0x00F0) >> 4
        hundreds = (q & 0x0F00) >> 8
        thousands = (q & 0xF000) >> 12

