class GoldenDUT:
    def __init__(self):
        self.q_reg = 0x0000  # 16-bit counter initialized to 0
        self.ena_reg = [0, 0, 0]  # Enable signals for [thousands, hundreds, tens]

    def load(self, signal_vector):
        # Handle reset condition
        if signal_vector['reset']:
            self.q_reg = 0x0000
            self.ena_reg = [0, 0, 0]
        else:
            self.increment_counter()

    def increment_counter(self):
        # Increment the counter
        self.q_reg += 1

        # Check BCD overflow for each digit and manage enable signals

        # Ones digit overflow
        if (self.q_reg & 0x000F) > 0x09:
            self.q_reg = (self.q_reg & 0xFFF0) + 0x10  # Carry overflow to the tens place
            self.ena_reg[0] = 1
        else:
            self.ena_reg[0] = 0

        # Tens digit overflow
        if ((self.q_reg >> 4) & 0x000F) > 0x09:
            self.q_reg = (self.q_reg & 0xFF0F) + 0x100  # Carry overflow to the hundreds place
            self.ena_reg[1] = 1
        else:
            self.ena_reg[1] = 0

        # Hundreds digit overflow
        if ((self.q_reg >> 8) & 0x000F) > 0x09:
            self.q_reg = (self.q_reg & 0xF0FF) + 0x1000  # Carry overflow to the thousands place
            self.ena_reg[2] = 1
        else:
            self.ena_reg[2] = 0

        # Thousands digit overflow
        # If thousands digit exceeds 9, reset q and enable signals.
        if ((self.q_reg >> 12) & 0x000F) > 0x09:
            self.q_reg = 0x0000
            self.ena_reg = [0, 0, 0]

