            self.q_reg = 0x0000
            self.ena_reg = [0, 0, 0]
            return

        self.q_reg, self.ena_reg = self.bcd_counter(self.q_reg)

    def check(self, signal_vector):
        if not signal_vector['check_en']:
            return True

        q_observed = signal_vector['q']
        ena_observed = signal_vector['ena']

        q_correct, ena_correct = self.q_reg, self.ena_reg

        if q_observed == q_correct and ena_observed == ena_correct:
            return True
        else:
            print(f"Scenario: {signal_vector['scenario']}, expected: q={q_correct}, ena={ena_correct}, observed: q={q_observed}, ena={ena_observed}")
            return False

    def bcd_counter(self, q):
        # Masks for each BCD digit
        ONES_MASK = 0x000F
        TENS_MASK = 0x00F0
        HUNDREDS_MASK = 0x0F00
        THOUSANDS_MASK = 0xF000

        # Extract BCD digits
        ones = q & ONES_MASK
        tens = (q & TENS_MASK) >> 4
        hundreds = (q & HUNDREDS_MASK) >> 8
        thousands = (q & THOUSANDS_MASK) >> 12

        # Initialize enable signals
        ena = [0, 0, 0]

        # Increment BCD counter
        ones += 1
        if ones > 9:
            ones = 0
            ena[0] = 1

        if ena[0]:
            tens += 1
            if tens > 9:
                tens = 0
                ena[1] = 1

        if ena[1]:
            hundreds += 1
            if hundreds > 9:
                hundreds = 0
                ena[2] = 1

        if ena[2]:
            thousands += 1
            if thousands > 9:
                thousands = 0

        q_next = (thousands << 12) | (hundreds << 8) | (tens << 4) | ones
        return q_next, ena
