class GoldenDUT:
    def __init__(self):
        # Initialize the internal state of the Golden DUT
        self.ones_reg = 0
        self.tens_reg = 0
        self.hundreds_reg = 0
        self.thousands_reg = 0
        self.ena_reg = 0

    def load(self, signal_vector):
        # Handle reset
        if signal_vector['reset']:
            self.reset()
        else:
            self.increment()

        # Update enable signals based on current BCD state
        self.update_enable_signals()

    def reset(self):
        # Reset internal states
        self.ones_reg = 0
        self.tens_reg = 0
        self.hundreds_reg = 0
        self.thousands_reg = 0
        self.ena_reg = 0

    def increment(self):
        # BCD increment with carry-over logic
        self.ones_reg += 1
        if self.ones_reg == 10:
            self.ones_reg = 0
            self.tens_reg += 1

        if self.tens_reg == 10:
            self.tens_reg = 0
            self.hundreds_reg += 1

        if self.hundreds_reg == 10:
            self.hundreds_reg = 0
            self.thousands_reg += 1

        if self.thousands_reg == 10:
            self.thousands_reg = 0

    def update_enable_signals(self):
        # Update enable signals based on BCD state
        self.ena_reg = 0

        # Enable for tens (ena[1])
        if self.ones_reg == 0:
            self.ena_reg |= 1 

        # Enable for hundreds (ena[2])
        if self.ones_reg == 0 and self.tens_reg == 0:
            self.ena_reg |= 2

        # Enable for thousands (ena[3])
        if self.ones_reg == 0 and self.tens_reg == 0 and self.hundreds_reg == 0:
            self.ena_reg |= 4

    def check(self, signal_vector):
        if signal_vector['check_en']:
            expected_q = (
                (self.thousands_reg << 12) |
                (self.hundreds_reg << 8) |
                (self.tens_reg << 4) |
                self.ones_reg
            )
            expected_ena = self.ena_reg
            observed_q = signal_vector['q']
            observed_ena = 0b111 & signal_vector['ena']  # Apply bit mask to ensure 3-bit width

            if expected_q != observed_q or expected_ena != observed_ena:
                print(f"Scenario: {signal_vector['scenario']}, "
                      f"expected q={expected_q:04x}, observed q={observed_q:04x}, "
                      f"expected ena={expected_ena:03b}, observed ena={observed_ena:03b}")
                return False

        return True
def check_dut(vectors_in):
