class GoldenDUT:
    def __init__(self):
        # Initialize the inner states/values of the flip-flops
        self.d1_reg = 0
        self.d2_reg = 0
        self.d3_reg = 0

    def load(self, signal_vector):
        # Get the input x from the signal vector
        x = signal_vector['x']

        # Calculate the next states of the D flip-flops based on current x and previous states
        next_d1 = self.xor_gate(x, self.d1_reg)
        next_d2 = self.and_gate(x, self.not_gate(self.d2_reg))  # Use not_gate to complement
        next_d3 = self.or_gate(x, self.not_gate(self.d3_reg))   # Use not_gate to complement

        # Update the flip-flop registers
        self.d1_reg = next_d1
        self.d2_reg = next_d2
        self.d3_reg = next_d3

    def check(self, signal_vector):
        # Extract the important signals
        z_observed = signal_vector['z']

        # Calculate expected output z based on current flip-flop states
        z_expected = self.xnor_gate([self.d1_reg, self.d2_reg, self.d3_reg])

        # Check if the expected output matches the observed output
        if z_expected != z_observed:
            print(f"Scenario: {signal_vector['scenario']}, expected: z={z_expected}, observed z={z_observed}")
            return False

        return True

    def xor_gate(self, a, b):
        return a ^ b

    def and_gate(self, a, b):
        return a & b

    def or_gate(self, a, b):
        return a | b

    def not_gate(self, a):
        # Implementing NOT gate (for a single bit)
        return 1 if a == 0 else 0

    def xnor_gate(self, inputs):
        # Implementing XNOR: result should be 1 if all inputs are the same (either all 1 or all 0)
        # Assure implementation checks all subsequent elements against the first to confirm equivalence
        first = inputs[0]
        if all(x == first for x in inputs):
            return 1
        else:
            return 0
