        self.ff1_reg = 0
        self.ff2_reg = 0
        self.ff3_reg = 0

    def load(self, signal_vector):
        x = signal_vector['x']

        # Update the flip-flop registers based on current input and previous state
        new_ff1_reg = self.xor_gate(x, self.ff1_reg)
        new_ff2_reg = self.and_gate(x, ~self.ff2_reg & 1)  # Correct complement operation
        new_ff3_reg = self.or_gate(x, ~self.ff3_reg & 1)   # Correct complement operation

        # Apply the new state updates after calculating to avoid sequential dependency errors
        self.ff1_reg = new_ff1_reg
        self.ff2_reg = new_ff2_reg
        self.ff3_reg = new_ff3_reg

    def check(self, signal_vector):
        expected_z = self.calculate_output_z()

        z_observed = signal_vector['z']
        if expected_z != z_observed:
            print(f"Scenario: {signal_vector['scenario']}, expected: z={expected_z}, observed: z={z_observed}")
            return False

        return True

    def xor_gate(self, x, d_ff_output):
        return x ^ d_ff_output

    def and_gate(self, x, d_ff_output_complemented):
        return x & d_ff_output_complemented

    def or_gate(self, x, d_ff_output_complemented):
        return x | d_ff_output_complemented

    def xnor_gate(self, d_ff1_output, d_ff2_output, d_ff3_output):
        return ~(d_ff1_output ^ d_ff2_output ^ d_ff3_output) & 1

    def calculate_output_z(self):
        # Calculate the output z based on the current flip-flop outputs
        return self.xnor_gate(self.ff1_reg, self.ff2_reg, self.ff3_reg)
