class GoldenDUT:
    def __init__(self):
        # Initialize internal registers
        self.in_reg = 0x00000000  # Previous input register
        self.out_reg = 0x00000000  # Output register, initially 0
        self.reset_reg = False     # Reset state

    def load(self, signal_vector):
        # Load input signals and update internal state
        in_new = signal_vector['in']
        reset_new = signal_vector['reset']

        # Determine if reset is active
        if reset_new:
            self.out_reg = 0x00000000  # Reset output register
        else:
            # Calculate transitions: bit was 1 before and 0 now
            transitions = self.in_reg & ~in_new
            # Capture transitions and keep previous high bits set
            self.out_reg |= transitions  # Capture transitions

        # Update input register for next cycle
        self.in_reg = in_new

    def check(self, signal_vector):
        # Compare expected output with actual output
        expected_out = self.out_reg
        observed_out = signal_vector['out']
        scenario_idx = signal_vector['scenario']

        # Check if the output matches
        if expected_out != observed_out:
            print(f"Scenario: {scenario_idx}, expected: out={expected_out:032b}, observed: out={observed_out:032b}")
            return False
        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

