    def __init__(self):
        # Initialize inner state registers
        self.state_reg = 0b01  # Initially weakly not-taken as per areset behavior

    def load(self, signal_vector):
        # Load input signals and update internal states
        areset = signal_vector.get('areset', 0)
        train_valid = signal_vector.get('train_valid', 0)
        train_taken = signal_vector.get('train_taken', 0)

        # Evaluate and update internal state
        self.state_reg = self.saturating_counter_rule(self.state_reg, areset, train_valid, train_taken)

    def check(self, signal_vector):
        # Check the expected output against the output signals from DUT
        expected_state = self.state_reg & 0b11  # Ensure the state is only 2 bits
        observed_state = signal_vector.get('state', None)

        if expected_state != observed_state:
            print(f"Scenario: {signal_vector['scenario']}, expected: state={bin(expected_state)}, observed state={bin(observed_state)}")
            return False
        return True

    def saturating_counter_rule(self, state, areset, train_valid, train_taken):
        if areset:
            return 0b01
        if train_valid:
            if train_taken:
                return min(state + 1, 0b11)
            else:
                return max(state - 1, 0b00)
        return state

