    MIN_STATE = 0b00  # 0 in decimal
    RESET_STATE = 0b01  # Weakly not-taken

    def __init__(self):
        # Set the initial state of the counter to the reset state
        self.state_reg = GoldenDUT.RESET_STATE

    def load(self, signal_vector):
        # Load the signal vector and update internal state based on inputs

        # Check for asynchronous reset
        if signal_vector['areset']:
            self.state_reg = GoldenDUT.RESET_STATE
        elif signal_vector['train_valid']:
            # Determine the next state based on train_taken signal
            if signal_vector['train_taken']:
                # Increment with saturation
                if self.state_reg < GoldenDUT.MAX_STATE:
                    self.state_reg += 1
            else:
                # Decrement with saturation
                if self.state_reg > GoldenDUT.MIN_STATE:
                    self.state_reg -= 1

    def check(self, signal_vector):
        # Check if the output state matches the expected state
        state_observed = signal_vector['state']
        state_expected = self.state_reg

        if state_expected != state_observed:
