    def __init__(self):
        self.q_reg = 0  # Initialize the state of the golden DUT
        self.last_a = 1  # Initialize tracking of `a` with a default that "holds" q in start
        self.last_check_en = False  # To track the last state of check_en

    def load(self, signal_vector):
        # Load the input signal 'a' and update the internal state accordingly
        a = signal_vector['a']
        check_en = signal_vector['check_en']

        # Evaluate logic only on check phases
        if check_en:
            # Transition condition to set q_reg to 4 when 'a' newly transitions to 1
            if a == 0:
                self.q_reg = (self.q_reg + 1) % 8  # Increment q modulo 8 when 'a' is 0
            elif a == 1 and self.last_a == 0:
                self.q_reg = 4  # Hold q at 4 in the first cycle when a changes from 0 to 1

        self.last_a = a  # Update to remember last 'a' state

    def check(self, signal_vector):
        # Determine expected output values
        q_observed = signal_vector['q']  # The observed output from DUT

        # Compare expected vs. observed and return the result
        expected = self.q_reg
        if expected != q_observed:
            print(f"Scenario: {signal_vector['scenario']}, expected: q={expected}, observed q={q_observed}")
            return False
        return True

    def process_signals(self, signals):
        # Process a series of signal vectors.
        for signal_vector in signals:
            self.load(signal_vector)
            if signal_vector['check_en']:
                if not self.check(signal_vector):
                    return False
        return True
