class GoldenDUT:
    def __init__(self):
        # Initialize the FSM state register
        self.state_reg = 0  # State A
        # Initialize the grant signals
        self.g1_reg = 0
        self.g2_reg = 0
        self.g3_reg = 0

    def load(self, signal_vector):
        # Update FSM state and grant signals based on current state and input requests
        r1 = signal_vector['r'] & 0b001
        r2 = (signal_vector['r'] >> 1) & 0b001
        r3 = (signal_vector['r'] >> 2) & 0b001

        # Call internal method to update state and grants
        self.state_reg, (self.g1_reg, self.g2_reg, self.g3_reg) = self.fsm_next_state(self.state_reg, r1, r2, r3, signal_vector['resetn'])

    def check(self, signal_vector):
        # Compare the expected output with the actual DUT output
        expected_g = (self.g1_reg, self.g2_reg, self.g3_reg)
        observed_g = (signal_vector['g'] & 0b001, (signal_vector['g'] >> 1) & 0b001, (signal_vector['g'] >> 2) & 0b001)

        if expected_g != observed_g:
            print(f"Scenario: {signal_vector['scenario']}, expected: g={expected_g}, observed: g={observed_g}")
            return False
        return True

    def fsm_next_state(self, current_state, r1, r2, r3, resetn):
        # Define state codes for convenience
        STATE_A, STATE_B, STATE_C, STATE_D = 0, 1, 2, 3

        if resetn == 0:
            return STATE_A, (0, 0, 0)

        if current_state == STATE_A:
            # Check transition conditions from state A based on priority
            if r1 == 1:
                return STATE_B, (1, 0, 0)
            elif r2 == 1:
                return STATE_C, (0, 1, 0)
            elif r3 == 1:
                return STATE_D, (0, 0, 1)
            else:
                return STATE_A, (0, 0, 0)

        elif current_state == STATE_B:
            # In state B, stay if r1 is still 1, else return to A
            if r1 == 1:
                return STATE_B, (1, 0, 0)
            else:
                return STATE_A, (0, 0, 0)

        elif current_state == STATE_C:
            # In state C, stay if r2 is still 1, else return to A
            if r2 == 1:
                return STATE_C, (0, 1, 0)
            else:
                return STATE_A, (0, 0, 0)

        elif current_state == STATE_D:
            # In state D, return to A as no grants are given in state D
            return STATE_A, (0, 0, 0)

        return current_state, (0, 0, 0)

