class GoldenDUT:
    def __init__(self):
        # State encoding
        self.STATE_A = 0b00
        self.STATE_B = 0b01
        self.STATE_C = 0b10
        self.STATE_D = 0b11

        # Initialize internal state and outputs
        self.state_reg = self.STATE_A
        self.g_reg = [0, 0, 0]

    def load(self, signal_vector):
        r = signal_vector['r']
        r1 = (r & 0b100) >> 2
        r2 = (r & 0b010) >> 1
        r3 = r & 0b001

        if signal_vector['resetn'] == 0:
            self.state_reg = self.STATE_A
        else:
            if self.state_reg == self.STATE_A:
                # Handle priority: r1 > r2 > r3
                if r1 == 1:
                    self.state_reg = self.STATE_B
                elif r2 == 1:
                    self.state_reg = self.STATE_C
                elif r3 == 1:
                    self.state_reg = self.STATE_D
            elif self.state_reg == self.STATE_B:
                if r1 == 0:
                    self.state_reg = self.STATE_A
            elif self.state_reg == self.STATE_C:
                if r2 == 0:
                    self.state_reg = self.STATE_A
            elif self.state_reg == self.STATE_D:
                if r1 == 1:
                    self.state_reg = self.STATE_B
                elif r2 == 1:
                    self.state_reg = self.STATE_C
                elif r3 == 0:
                    self.state_reg = self.STATE_A

    def check(self, signal_vector):
        g_expected = self.determine_expected_grants()
        g_observed = [
            (signal_vector['g'] & 0b100) >> 2,
            (signal_vector['g'] & 0b010) >> 1,
            signal_vector['g'] & 0b001
        ]

        if g_expected != g_observed:
            print(f"Scenario: {signal_vector['scenario']}, expected: g={g_expected}, observed: g={g_observed}")
            return False
        return True

    def determine_expected_grants(self):
        # Correct grant calculation logic
        g = [0, 0, 0]
        if self.state_reg == self.STATE_B:
            g[0] = 1
        elif self.state_reg == self.STATE_C:
            g[1] = 1
        elif self.state_reg == self.STATE_D:
            g[2] = 1
        return g
