        # Initial state is STATE_A (0)
        self.state_reg = 0
        # Initial output values, g1=0, g2=0, g3=0
        self.g_reg = 0b000

    def load(self, signal_vector):
        # Load the signal vector and update state/output
        if signal_vector['resetn'] == 0:
            # On reset, go back to STATE_A and reset all grants
            self.state_reg = 0  # STATE_A
            self.g_reg = 0b000  # g1=g2=g3=0
        else:
            self.update_state_and_output(signal_vector['r'])

    def update_state_and_output(self, r):
        # Extract individual request signals from the request vector
        r1 = (r >> 2) & 1
        r2 = (r >> 1) & 1
        r3 = r & 1

        # FSM logic based on the current state and requests
        if self.state_reg == 0:  # STATE_A
            if r1:
                self.state_reg = 1  # Transition to STATE_B
                self.g_reg = 0b100  # Set g1=1
            elif r2:
                self.state_reg = 2  # Transition to STATE_C
                self.g_reg = 0b010  # Set g2=1
            elif r3:
                self.state_reg = 3  # Transition to STATE_D
                self.g_reg = 0b001  # Set g3=1
            else:
                self.g_reg = 0b000  # Ensure outputs are reset when no requests are active
        elif self.state_reg == 1:  # STATE_B
            self.g_reg = 0b100  # Maintain g1=1
            if not r1:
                self.state_reg = 0  # Return to STATE_A if r1 is not asserted
        elif self.state_reg == 2:  # STATE_C
            self.g_reg = 0b010  # Maintain g2=1
            if not r2:
                self.state_reg = 0  # Return to STATE_A if r2 is not asserted
        elif self.state_reg == 3:  # STATE_D
            self.g_reg = 0b001  # Maintain g3=1
            if not r3:
                self.state_reg = 0  # Return to STATE_A if r3 is not asserted

    def check(self, signal_vector):
