class GoldenDUT:
    def __init__(self):
        # Initial state of the FSM is STATE_A
        self.state_reg = 0b000
        # Initial grant outputs
        self.g1_reg = 0
        self.g2_reg = 0
        self.g3_reg = 0

    def load(self, signal_vector):
        # Load input signals
        r1 = (signal_vector['r'] & 0b100) >> 2
        r2 = (signal_vector['r'] & 0b010) >> 1
        r3 = signal_vector['r'] & 0b001
        resetn = signal_vector['resetn']

        # Check if reset is active low, reset state to STATE_A
        if resetn == 0:
            self.state_reg = 0b000
            self.g1_reg = 0
            self.g2_reg = 0
            self.g3_reg = 0
        else:
            # Update the current state and grant outputs
            self.state_reg, self.g1_reg, self.g2_reg, self.g3_reg = self.arbiter_fsm_rules(r1, r2, r3, self.state_reg)

    def check(self, signal_vector):
        if not signal_vector['check_en']:
            return True

        # Observed outputs from DUT
        g_observed = signal_vector['g']

        # Check the DUT outputs against expected outputs
        if ((self.g1_reg == ((g_observed & 0b001) != 0)) and
            (self.g2_reg == ((g_observed & 0b010) != 0)) and
            (self.g3_reg == ((g_observed & 0b100) != 0))):
            return True
        else:
            # Print error message if mismatch occurs
            print(f"Scenario: {signal_vector['scenario']}, expected: g={self.g1_reg * 0b001 | self.g2_reg * 0b010 | self.g3_reg * 0b100:03b}, observed: g={g_observed:03b}")
            return False

    def arbiter_fsm_rules(self, r1, r2, r3, current_state):
        # State encoding
        STATE_A = 0b000
        STATE_B = 0b001
        STATE_C = 0b010
        STATE_D = 0b011

        # Default outputs
        next_state = STATE_A
        g1 = 0
        g2 = 0
        g3 = 0

        # FSM logic for states and transitions
        if current_state == STATE_A:
            if r1:
                next_state = STATE_B
                g1 = 1
            elif r2:
                next_state = STATE_C
                g2 = 1
            elif r3:
                next_state = STATE_D
                g3 = 1
        elif current_state == STATE_B:
            g1 = 1  # Maintain grant when in state B
            if r1:
                next_state = STATE_B
            else:
                next_state = STATE_A
        elif current_state == STATE_C:
            g2 = 1  # Maintain grant when in state C
            if r2:
                next_state = STATE_C
            else:
                next_state = STATE_A
        elif current_state == STATE_D:
            g3 = 1  # Maintain grant when in state D
            if r3:
                next_state = STATE_D
            else:
                next_state = STATE_A

        return next_state, g1, g2, g3
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
