class GoldenDUT:
    def __init__(self):
        # Define initial state and output registers
        self.state_reg = 0b00  # 'A' initial state
        self.g1_reg = 0
        self.g2_reg = 0
        self.g3_reg = 0

    def load(self, signal_vector):
        # Load input signals
        resetn = signal_vector['resetn']
        r = signal_vector.get('r', 0)

        # Extract individual request signals
        r1, r2, r3 = (r >> 2) & 0b1, (r >> 1) & 0b1, r & 0b1

        # Handle reset
        if resetn == 0:
            self.state_reg = 0b00  # Reset to state 'A'
            self.g1_reg = self.g2_reg = self.g3_reg = 0
        else:
            self.state_reg, [_, self.g1_reg, self.g2_reg, self.g3_reg] = self.fsm_rules(self.state_reg, [r1, r2, r3])

    def check(self, signal_vector):
        # Compare DUT output signals with expected values
        expected_g1 = self.g1_reg
        expected_g2 = self.g2_reg
        expected_g3 = self.g3_reg

        observed_g1 = signal_vector.get('g', 0) & 0b01
        observed_g2 = (signal_vector.get('g', 0) >> 1) & 0b01
        observed_g3 = (signal_vector.get('g', 0) >> 2) & 0b01

        valid = (expected_g1 == observed_g1) and (expected_g2 == observed_g2) and (expected_g3 == observed_g3)
        if not valid:
            print(f"Scenario: {signal_vector['scenario']}, expected: g1={expected_g1}, g2={expected_g2}, g3={expected_g3}, "
                  f"observed: g1={observed_g1}, g2={observed_g2}, g3={observed_g3}")

        return valid

    def fsm_rules(self, current_state, r):
        # FSM Rules
        A, B, C, D = 0b00, 0b01, 0b10, 0b11
        r1, r2, r3 = r

        next_state = current_state
        g = [0, 0, 0, 0]

        if current_state == A:
            if r1:
                next_state = B
            elif r2:
                next_state = C
            elif r3:
                next_state = D

        elif current_state == B:
            g[1] = 1
            if not r1:
                next_state = A

        elif current_state == C:
            g[2] = 1
            if not r2:
                next_state = A

        elif current_state == D:
            g[3] = 1
            if r1 == 0 and r2 == 0 and r3 == 0:
                next_state = A

        return next_state, g
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
