class GoldenDUT:
    def __init__(self):
        # Initialize the inner state registers 
        self.in_message_reg = False
        self.byte_counter_reg = 0
        self.done_reg = False

    def load(self, signal_vector):
        if signal_vector['reset']:
            # Reset all registers to initial state
            self.in_message_reg = False
            self.byte_counter_reg = 0
            self.done_reg = False
        else:
            input_value = signal_vector['in']

            if input_value & 0b00001000:  # Check if in[3] == 1
                self.in_message_reg = True
                self.byte_counter_reg = 1
            elif self.in_message_reg:
                self.byte_counter_reg += 1
                # Ensure counter does not exceed three bits (not strictly necessary here but good practice)
                self.byte_counter_reg &= 0b111

            if self.in_message_reg and self.byte_counter_reg == 3:
                self.done_reg = True
            else:
                self.done_reg = False

    def check(self, signal_vector):
        # Get the observed 'done' signal from the DUT
        done_observed = signal_vector['done']

        if signal_vector['check_en']:
            # Compare the expected 'done' signal with the observed one
            if self.done_reg != done_observed:
                print(f"Scenario: {signal_vector['scenario']}, expected: done={self.done_reg}, observed done={done_observed}")
                return False
        return True

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

