        # Initialize internal state registers
        self.p_reg = 0
        self.q_reg = 0
        self.q_next = 0

    def load(self, signal_vector):
        # Load the signal vector and update the internal states
        a = signal_vector.get('a', 0)

        # Update p_reg based on the current logic
        if a == 1:
            self.p_reg = 1
        else:
            self.p_reg = 0

        # Update q_next to be what q_reg should be in the next cycle
        self.q_next = self.p_reg

        # Now update q_reg to the previously computed next state
        # Ensure a one-clock cycle delay for q_reg
        self.q_reg = self.q_next  # This line remains, considering the queue mechanism

