class GoldenDUT:
    def __init__(self):
        # Initialize states
        self.OFF = 0
        self.ON = 1
        self.state_reg = self.OFF
        self.out_reg = 0  # Output based on initial state, OFF=0

    def load(self, signal_vector):
        # Handle asynchronous reset
        if signal_vector['areset']:
            self.state_reg, self.out_reg = self.apply_asynchronous_reset()
        else:
            # Transition state based on current inputs and state
            self.state_reg, self.out_reg = self.moore_state_machine_rules(
                self.state_reg, signal_vector['j'], signal_vector['k'])

    def check(self, signal_vector):
        # Compare expected output with actual output
        expected_out = self.out_reg
        observed_out = signal_vector['out']
        if expected_out != observed_out:
            print(f"Scenario: {signal_vector['scenario']}, expected: out={expected_out}, observed out={observed_out}")
            return False
        return True

    def moore_state_machine_rules(self, current_state, j, k):
        # Define state transition logic
        if current_state == self.OFF:
            next_state = self.ON if j else self.OFF
        elif current_state == self.ON:
            next_state = self.OFF if k else self.ON

        output = next_state  # Output corresponds to the current state
        return next_state, output

    def apply_asynchronous_reset(self):
        # Reset the state to OFF and output to 0
        return self.OFF, 0

