class GoldenDUT:
    def __init__(self):
        # Initialize states
        self.IDLE = 0
        self.START_BIT = 1
        self.DATA_BITS = 2
        self.STOP_BIT = 3
        self.ERROR = 4

        # Initial inner registers
        self.state_reg = self.IDLE
        self.data_bit_count_reg = 0
        self.expected_done_reg = 0

    def load(self, signal_vector):
        # Update inner state based on the inputs
        if signal_vector['reset'] == 1:
            self.state_reg = self.IDLE
            self.data_bit_count_reg = 0
            self.expected_done_reg = 0
        else:
            in_bit = signal_vector['in']
            if self.state_reg == self.IDLE:
                if in_bit == 0:
                    self.state_reg = self.START_BIT
                self.expected_done_reg = 0

            elif self.state_reg == self.START_BIT:
                self.state_reg = self.DATA_BITS
                self.data_bit_count_reg = 0
                self.expected_done_reg = 0

            elif self.state_reg == self.DATA_BITS:
                self.data_bit_count_reg += 1
                if self.data_bit_count_reg == 8:
                    self.state_reg = self.STOP_BIT
                self.expected_done_reg = 0

            elif self.state_reg == self.STOP_BIT:
                if in_bit == 1:
                    self.expected_done_reg = 1
                    self.state_reg = self.IDLE
                else:
                    self.state_reg = self.ERROR
                    self.expected_done_reg = 0

            elif self.state_reg == self.ERROR:
                if in_bit == 1:
                    self.state_reg = self.IDLE
                self.expected_done_reg = 0

    def check(self, signal_vector):
        done_observed = signal_vector['done']
        if signal_vector['check_en']:
            if done_observed != self.expected_done_reg:
                print(f"Scenario: {signal_vector['scenario']}, expected: done={self.expected_done_reg}, observed done={done_observed}")
                return False
        return True

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

