class GoldenDUT:
    def __init__(self):
        self.start_bit = 0
        self.stop_bit = 1
        self.data_bits_count = 8
        self.bits_received = []
        self.done_reg = False
        self.expected_data_length = self.data_bits_count + 2  # Start bit, data bits, stop bit

    def load(self, signal_vector):
        if signal_vector['reset']:
            self.bits_received = []
            self.done_reg = False
        else:
            in_bit = signal_vector['in']
            if in_bit in [0, 1]:
                # Only start populating bits_received when start bit is encountered
                if not self.bits_received and in_bit == self.start_bit:
                    self.bits_received.append(in_bit)
                elif self.bits_received:
                    self.bits_received.append(in_bit)
                # Ensure we do not exceed the expected length
                if len(self.bits_received) > self.expected_data_length:
                    self.bits_received.pop(0)

    def check(self, signal_vector):
        if signal_vector['check_en']:
            valid_byte = self._is_valid_byte()
            a_observed = signal_vector['done']
            if valid_byte != a_observed:
                print(f"Scenario: {signal_vector['scenario']}, expected: done={valid_byte}, observed done={a_observed}")
                return False
        return True

    def _is_valid_byte(self):
        # Check if we've received the correct number of bits
        if len(self.bits_received) == self.expected_data_length:
            # Verify start, data bits, and stop bit
            if (self.bits_received[0] == self.start_bit and 
                all(bit in [0, 1] for bit in self.bits_received[1:-1]) and 
                self.bits_received[-1] == self.stop_bit):
                return True
        return False

    def reset(self):
        """Optional reset method to clear the state manually if needed elsewhere."""
        self.bits_received = []
        self.done_reg = False
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

