class GoldenDUT:
    def __init__(self):
        self.q_reg = 0  # 16-bit BCD counter
        self.ena_reg = 0  # 3-bit enable signals
        self.clk_pulses_reg = 0  # Clock pulse counter

    def load(self, signal_vector):
        # Handle synchronous reset
        if signal_vector['reset']:
            self.q_reg = 0
            self.ena_reg = 0
            self.clk_pulses_reg = 0
        else:
            self.clk_pulses_reg += 1

            # Calculate BCD digits
            ones = self.clk_pulses_reg % 10
            tens = (self.clk_pulses_reg // 10) % 10
            hundreds = (self.clk_pulses_reg // 100) % 10
            thousands = (self.clk_pulses_reg // 1000) % 10

            self.q_reg = (thousands << 12) | (hundreds << 8) | (tens << 4) | ones

            # Compute enable signals based on BCD transitions
            ena_tens = 1 if ones == 0 and (self.clk_pulses_reg % 10) == 0 else 0
            ena_hundreds = 1 if tens == 0 and ones == 0 and (self.clk_pulses_reg // 10) % 10 == 0 else 0
            ena_thousands = 1 if hundreds == 0 and tens == 0 and ones == 0 and (self.clk_pulses_reg // 100) % 10 == 0 else 0
            self.ena_reg = (ena_thousands << 2) | (ena_hundreds << 1) | ena_tens

    def check(self, signal_vector):
        if signal_vector['check_en']:
            q_observed = signal_vector['q']
            ena_observed = signal_vector['ena']

            if (q_observed != self.q_reg) or (ena_observed != self.ena_reg):
                print(f"Scenario: {signal_vector['scenario']}, expected: q={self.q_reg:016b}, ena={self.ena_reg:03b}, "
                      f"observed: q={q_observed:016b}, ena={ena_observed:03b}")
                return False
        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

