        self.q_reg = 0x0000
        self.ena_reg = 0b000

    def load(self, signal_vector):
        reset = signal_vector['reset']

        if reset:
            self.q_reg = 0x0000
            self.ena_reg = 0b000
        else:
            # Increment the BCD counter
            ones = self.q_reg & 0x0F                 # Extract ones digit
            tens = (self.q_reg >> 4) & 0x0F         # Extract tens digit
            hundreds = (self.q_reg >> 8) & 0x0F     # Extract hundreds digit
            thousands = (self.q_reg >> 12) & 0x0F   # Extract thousands digit

            # Carry logic for BCD
            ones += 1
            ena_ones = ones > 9
            if ena_ones:
                ones = 0

            tens += 1 if ena_ones else 0
            ena_tens = tens > 9
            if ena_tens:
                tens = 0

            hundreds += 1 if ena_tens else 0
            ena_hundreds = hundreds > 9
            if ena_hundreds:
                hundreds = 0

            thousands += 1 if ena_hundreds else 0
            ena_thousands = thousands > 9
            if ena_thousands:
                thousands = 0

            # Construct the q value
            self.q_reg = (thousands << 12) | (hundreds << 8) | (tens << 4) | ones
            # Fix enable signal to correctly indicate carry propagation
            self.ena_reg = (ena_hundreds << 2) | (ena_tens << 1) | ena_ones

    def check(self, signal_vector):
        q_observed = signal_vector['q']
        ena_observed = (signal_vector['ena'] & 0b1110) >> 1  # Extract correct bits for ena

