        if reset:
            self.q_reg = 0b0000_0000_0000_0000
            self.ena_reg = 0b000
            self.clk_cycles_reg = 0
        else:
            self.clk_cycles_reg += 1

        self.simulate_bcd_counter()  # Calculate q_reg and ena_reg based on clk_cycles_reg

