        ones = self.clk_cycles_reg % 10
        tens = (self.clk_cycles_reg // 10) % 10
        hundreds = (self.clk_cycles_reg // 100) % 10
        thousands = (self.clk_cycles_reg // 1000) % 10

        self.q_reg = (thousands << 12) | (hundreds << 8) | (tens << 4) | ones

        # Corrected logic for enable signals
        ena_1 = 1 if ones == 0 and tens != 0 else 0
        ena_2 = 1 if tens == 0 and hundreds != 0 else 0
        ena_3 = 1 if hundreds == 0 and thousands != 0 else 0

        self.ena_reg = (ena_3 << 2) | (ena_2 << 1) | ena_1

    def check(self, signal_vector):
        q_observed = signal_vector['q']
        ena_observed = signal_vector['ena']  # Correctly capture ena signal from DUT output

