class GoldenDUT:
    def __init__(self):
        # Initialize the flip-flops with 0
        self.q1_reg = 0
        self.q2_reg = 0
        self.q3_reg = 0

    def xor_gate(self, a, b):
        return a ^ b

    def and_gate(self, a, b):
        return a & b

    def or_gate(self, a, b):
        return a | b

    def xnor_gate(self, a, b, c):
        return ~(a ^ b ^ c) & 0b1  # Mask to keep it as a single bit

    def load(self, signal_vector):
        # Extract the input signal 'x'
        x = signal_vector['x']

        # Perform the logic operations
        d1 = self.xor_gate(x, self.q1_reg)  # Ensure correct state update
        d2 = self.and_gate(x, ~self.q2_reg & 0b1)  # Ensure single bit and correct complement
        d3 = self.or_gate(x, ~self.q3_reg & 0b1)  # Ensure single bit and correct complement

        # Update the flip-flops
        self.q1_reg = d1
        self.q2_reg = d2
        self.q3_reg = d3

    def check(self, signal_vector):
        # Calculate expected output 'z'
        expected_z = self.xnor_gate(self.q1_reg, self.q2_reg, self.q3_reg)

        # Get observed output 'z' from the signal vector
        observed_z = signal_vector['z']

        # Check if expected and observed outputs match
        if expected_z == observed_z:
            return True
        else:
            print(f"Scenario: {signal_vector['scenario']}, expected: z={expected_z}, observed z={observed_z}")
            return False

    # Additional methods can be added if needed, but are not necessary in this case.
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
