        if signal_vector['reset']:
            self.out_reg = 0
        else:
            prev_input = self.in_reg
            curr_input = signal_vector['in']
            self.out_reg |= self.capture_transitions(prev_input, curr_input)
            self.out_reg &= 0xFFFFFFFF  # Ensure 32-bit limit
        self.in_reg = signal_vector['in']

    def check(self, signal_vector):
        if signal_vector['check_en']:
            expected_out = self.out_reg
            observed_out = signal_vector['out']
            if expected_out != observed_out:
                print(f"Scenario: {signal_vector['scenario']}, expected: out={expected_out:032b}, observed: out={observed_out:032b}")
                return False
        return True

