        # Initialize internal state to the reset condition
        self.state_reg = 0b01  # weakly not-taken

    def load(self, signal_vector):
        # Apply reset if necessary, otherwise update state based on inputs
        if signal_vector['areset']:
            self.state_reg = self.apply_reset()
        else:
            self.state_reg = self.saturating_counter_next_state(
                self.state_reg,
                signal_vector['train_valid'],
                signal_vector['train_taken']
            )

    def check(self, signal_vector):
        # Compare expected state with observed state
