class State(Enum):
    A = 0
    B = 1
    C = 2
    D = 3

class GoldenDUT:
    def __init__(self):
        self.state_reg = State.A
        self.g_reg = 0b000

    def load(self, signal_vector):
        if not signal_vector['resetn']:
            self.state_reg = State.A
            self.g_reg = 0b000
        else:
            r = (signal_vector['r'] & 0b111)
            self.state_reg, self.g_reg = self.fsm_next_state(self.state_reg, r)

    def check(self, signal_vector):
        if signal_vector['check_en']:
            g_observed = (signal_vector['g'] & 0b111)
            if self.g_reg != g_observed:
                print(f"Scenario: {signal_vector['scenario']}, expected: g={bin(self.g_reg)}, observed g={bin(g_observed)}")
                return False
        return True

    def fsm_next_state(self, current_state, r):
        # Priority from highest to lowest: r1(4) -> r2(2) -> r3(1)
        if current_state == State.A:
            if r & 0b001:  # r1 has highest priority
                return State.B, 0b100  # g1
            elif r & 0b010:  # r2 has second priority
                return State.C, 0b010  # g2
            elif r & 0b100:  # r3 has lowest priority
                return State.D, 0b001  # g3
            else:
                return State.A, 0b000

        elif current_state == State.B:
            if r & 0b001:
                return State.B, 0b100  # g1 remains active
            else:
                return State.A, 0b000

        elif current_state == State.C:
            if r & 0b010:
                return State.C, 0b010  # g2 remains active
            else:
                return State.A, 0b000

        elif current_state == State.D:
            # Stay in D if there's a request for r3, otherwise return to A
            if r & 0b100:
                return State.D, 0b001  # g3 remains active
            else:
                return State.A, 0b000
