    def __init__(self):
        # State codes
        self.STATE_A = 0b00
        self.STATE_B = 0b01
        self.STATE_C = 0b10
        self.STATE_D = 0b11

        # Initialize registers
        self.current_state_reg = self.STATE_A
        self.g_reg = [0, 0, 0]  # g[1], g[2], g[3]

    def load(self, signal_vector):
        # Active-low reset
        if signal_vector['resetn'] == 0:
            self.current_state_reg = self.STATE_A
            self.g_reg = [0, 0, 0]
        else:
            r = [signal_vector['r'] & 0x1, (signal_vector['r'] >> 1) & 0x1, (signal_vector['r'] >> 2) & 0x1]
            self.current_state_reg, self.g_reg = self.ideal_fsm_rule(r, self.current_state_reg)

    def check(self, signal_vector):
        if signal_vector['check_en']:
            # Capture the observed outputs from DUT
            g_observed = [signal_vector['g'] & 0x1, (signal_vector['g'] >> 1) & 0x1, (signal_vector['g'] >> 2) & 0x1]

            # Compare expected vs observed outputs
            if self.g_reg != g_observed:
                print(f"Scenario: {signal_vector['scenario']}, expected: g={self.g_reg}, observed g={g_observed}")
                return False
        return True

    def ideal_fsm_rule(self, r, current_state):
        if current_state == self.STATE_A:
            if r[0] == 1:  # Priority to r[0]
                next_state = self.STATE_B
                g = [1, 0, 0]
            elif r[1] == 1:  # Then r[1]
                next_state = self.STATE_C
                g = [0, 1, 0]
            elif r[2] == 1:  # Lastly r[2]
                next_state = self.STATE_D
                g = [0, 0, 1]
            else:
                next_state = self.STATE_A
                g = [0, 0, 0]

        elif current_state == self.STATE_B:
            g = [1, 0, 0]
            if r[0] == 1:
                next_state = self.STATE_B
            else:
