    def __init__(self):
        # State encoding
        self.STATE_A = 0b00
        self.STATE_B = 0b01
        self.STATE_C = 0b10
        self.STATE_D = 0b11

        # Set initial state and output registers
        self.state_reg = self.STATE_A
        self.next_state_reg = self.STATE_A
        self.g1_reg = 0
        self.g2_reg = 0
        self.g3_reg = 0

    def load(self, signal_vector):
        # Unpack signals from signal vector
        r1 = (signal_vector['r'] >> 2) & 0x1
        r2 = (signal_vector['r'] >> 1) & 0x1
        r3 = signal_vector['r'] & 0x1
        resetn = signal_vector['resetn']

        # Reset logic
        if not resetn:
            self.state_reg = self.STATE_A
        else:
            # Update the current state to the next state
            self.state_reg = self.next_state_reg

        # Transition logic based on the FSM rules with priority enforcement
        if self.state_reg == self.STATE_A:
            # Enforce priority: r1 > r2 > r3
            if r1:
                self.next_state_reg = self.STATE_B
            elif r2:
                self.next_state_reg = self.STATE_C
            elif r3:
                self.next_state_reg = self.STATE_D
            else:
                self.next_state_reg = self.STATE_A

        elif self.state_reg == self.STATE_B:
            if not r1:
                self.next_state_reg = self.STATE_A

        elif self.state_reg == self.STATE_C:
            if not r2:
                self.next_state_reg = self.STATE_A

        elif self.state_reg == self.STATE_D:
            if not r3:
                self.next_state_reg = self.STATE_A

    def check(self, signal_vector):
        # Determine expected outputs
        g1_expected = 1 if self.state_reg == self.STATE_B else 0
        g2_expected = 1 if self.state_reg == self.STATE_C else 0
        g3_expected = 1 if self.state_reg == self.STATE_D else 0

        # Observed outputs from DUT
        g1_observed = signal_vector['g'] & 0x1
        g2_observed = (signal_vector['g'] >> 1) & 0x1
        g3_observed = (signal_vector['g'] >> 2) & 0x1

