class GoldenDUT:
    def __init__(self):
        # Initialize state and inner values
        self.state_reg = 0b00  # State A
        self.g1_reg = 0
        self.g2_reg = 0
        self.g3_reg = 0

    def load(self, signal_vector):
        resetn = signal_vector['resetn']
        r_values = signal_vector['r']

        # Extract requests for clarity
        r1, r2, r3 = (r_values >> 2) & 0x1, (r_values >> 1) & 0x1, r_values & 0x1

        # FSM behavior
        if resetn == 0:
            # Reset to State A
            self.state_reg = 0b00
        else:
            if self.state_reg == 0b00:  # State A
                if r1 == 1:
                    self.state_reg = 0b01  # State B
                elif r2 == 1 and r1 == 0:
                    self.state_reg = 0b10  # State C
                elif r3 == 1 and r1 == 0 and r2 == 0:
                    self.state_reg = 0b11  # State D
                # Remain in State A if no requests
            elif self.state_reg == 0b01:  # State B
                if r1 == 0:
                    self.state_reg = 0b00  # State A
                # Remain in State B if r1 is 1
            elif self.state_reg == 0b10:  # State C
                if r2 == 0:
                    self.state_reg = 0b00  # State A
                # Remain in State C if r2 is 1
            elif self.state_reg == 0b11:  # State D
                if r3 == 0:
                    self.state_reg = 0b00  # State A
                # Remain in State D if r3 is 1

        # Update grant outputs based on state
        self.g1_reg = 1 if self.state_reg == 0b01 else 0
        self.g2_reg = 1 if self.state_reg == 0b10 else 0
        self.g3_reg = 1 if self.state_reg == 0b11 else 0

    def check(self, signal_vector):
        observed_g1 = signal_vector.get('g1', 0)
        observed_g2 = signal_vector.get('g2', 0)
        observed_g3 = signal_vector.get('g3', 0)

        expected_g1 = self.g1_reg
        expected_g2 = self.g2_reg
        expected_g3 = self.g3_reg

        if expected_g1 == observed_g1 and expected_g2 == observed_g2 and expected_g3 == observed_g3:
            return True
        else:
            print(f"Scenario: {signal_vector['scenario']}, expected: g1={expected_g1}, g2={expected_g2}, g3={expected_g3}, "
                  f"observed g1={observed_g1}, g2={observed_g2}, g3={observed_g3}")
            return False
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
