class GoldenDUT:
    def __init__(self):
        self.IDLE = 0
        self.BYTE_1_RECEIVED = 1
        self.BYTE_2_RECEIVED = 2
        self.BYTE_3_RECEIVED = 3

        self.fsm_state_reg = self.IDLE
        self.done_reg = False
        self.done_signal_latched = False

    def load(self, signal_vector):
        in_signal = signal_vector['in']
        reset = signal_vector['reset']

        if reset:
            self.fsm_state_reg = self.IDLE
            self.done_reg = False
            self.done_signal_latched = False
        else:
            if not self.done_signal_latched:
                if self.fsm_state_reg == self.IDLE:
                    if (in_signal & 0b00001000) != 0:
                        self.fsm_state_reg = self.BYTE_1_RECEIVED

                elif self.fsm_state_reg == self.BYTE_1_RECEIVED:
                    self.fsm_state_reg = self.BYTE_2_RECEIVED

                elif self.fsm_state_reg == self.BYTE_2_RECEIVED:
                    self.fsm_state_reg = self.BYTE_3_RECEIVED

                elif self.fsm_state_reg == self.BYTE_3_RECEIVED:
                    # Signal done and latch it for one cycle
                    self.done_reg = True
                    self.done_signal_latched = True
            else:
                # Keep the done signal high for one additional cycle before resetting
                self.done_reg = False
                self.done_signal_latched = False
                self.fsm_state_reg = self.IDLE

    def check(self, signal_vector):
        expected_done = self.done_reg
        observed_done = signal_vector['done']

        if expected_done != observed_done:
            print(f"Scenario: {signal_vector['scenario']}, expected: done={expected_done}, observed done={observed_done}")
            return False
        return True

    def reset_fsm(self):
        """Manually reset FSM; useful for additional requirements or functions."""
        self.fsm_state_reg = self.IDLE
        self.done_reg = False
        self.done_signal_latched = False
