class GoldenDUT:
    def __init__(self):
        self.state_reg = 0      # 0 = waiting, 1 = byte 1 received, 2 = byte 2 received
        self.done_reg = 0
        self.reset_reg = 0

    def load(self, signal_vector):
        # Load signals, especially 'in' and 'reset'
        input_byte = signal_vector['in']
        self.reset_reg = signal_vector['reset']

        if self.reset_reg:
            self.state_reg = 0
            self.done_reg = 0
        else:
            self.state_reg, self.done_reg = self.update_state(input_byte)

    def update_state(self, input_byte):
        # Use bit mask to ensure in[3] is being checked
        if self.state_reg == 0:
            if input_byte & 0b00001000:  # Check in[3]
                return 1, 0
            else:
                return 0, 0
        elif self.state_reg == 1:
            return 2, 0
        elif self.state_reg == 2:
            return 0, 1

    def check(self, signal_vector):
        done_observed = signal_vector['done']
        expected_done = self.done_reg

        if done_observed != expected_done:
            print(f"Scenario: {signal_vector['scenario']}, expected: done={expected_done}, observed: done={done_observed}")
            return False
        return True

