        self.p_reg = 0  # Initialized to zero
        self.q_reg = 0  # Initialized to zero
        self.clock_reg = 0  # Track the clock state
        self.prev_p_reg = 0  # Previous state to store last p value

    def load(self, signal_vector):
        # Update the clock state
        self.clock_reg = not self.clock_reg  # Toggle clock state for each "load" call

        # If clock is rising edge, process inputs
        if self.clock_reg == 1:
            self.prev_p_reg = self.p_reg  # Store current p value as previous
            self._process_inputs(signal_vector['a'])

    def _process_inputs(self, a):
        # Logic to update internal registers on rising edge
        self.p_reg = a
        # Update q_reg to reflect the previous state of p_reg at every cycle
        self.q_reg = self.prev_p_reg

