class GoldenDUT:
    def __init__(self):
        # Initialize registers and enable signals; initially set all to zero
        self.q_reg = 0x0000  # 16-bit BCD counter
        self.ena_reg = [0b0, 0b0, 0b0]  # Enable signals for [thousands, hundreds, tens]

    def load(self, signal_vector):
        # Extract signals from input vector
        reset = signal_vector['reset']

        if reset:
            # Reset the counter to 0 if reset is high
            self.q_reg = 0x0000
            self.ena_reg = [0b0, 0b0, 0b0]
        else:
            # Process the counter logic
            self.q_reg, self.ena_reg = self.bcd_counter_rules(self.q_reg)

    def bcd_counter_rules(self, current_q):
        # Extract individual BCD digits
        ones = current_q & 0xF
        tens = (current_q >> 4) & 0xF
        hundreds = (current_q >> 8) & 0xF
        thousands = (current_q >> 12) & 0xF

        # Calculate next state of ones digit
        if ones == 9:
            next_ones = 0
            enable_tens = True
        else:
            next_ones = ones + 1
            enable_tens = False

        # Calculate next state and enable for tens digit
        if enable_tens:
            if tens == 9:
                next_tens = 0
                enable_hundreds = True
            else:
                next_tens = tens + 1
                enable_hundreds = False
        else:
            next_tens = tens
            enable_hundreds = False

        # Calculate next state and enable for hundreds digit
        if enable_hundreds:
            if hundreds == 9:
                next_hundreds = 0
                enable_thousands = True
            else:
                next_hundreds = hundreds + 1
                enable_thousands = False
        else:
            next_hundreds = hundreds
            enable_thousands = False

        # Calculate next state of thousands digit
        if enable_thousands:
            next_thousands = thousands + 1 if thousands < 9 else 0
        else:
            next_thousands = thousands

        # Compose the next state of q
        next_q = (next_thousands << 12) | (next_hundreds << 8) | (next_tens << 4) | next_ones

        # Create enable signals
        ena = [
            0b1 if enable_thousands else 0b0,
            0b1 if enable_hundreds else 0b0,
            0b1 if enable_tens else 0b0
        ]

        return next_q, ena

    def check(self, signal_vector):
        # Check output q and ena signals with expected values
        expected_q = self.q_reg
        expected_ena = self.ena_reg

