    def __init__(self):
        self.q_reg = 0x0000  # Initialize BCD counter to zero
        self.ena_reg = 0b000  # Initialize enable signals to zero

    def load(self, signal_vector):
        if signal_vector.get('reset', 0):
            # Synchronous reset sets the counter to zero
            self.q_reg = 0x0000
            self.ena_reg = 0b000
        else:
            ena_3, ena_2, ena_1 = 0, 0, 0
            ones = self.q_reg & 0x000F
            tens = (self.q_reg & 0x00F0) >> 4
            hundreds = (self.q_reg & 0x0F00) >> 8
            thousands = (self.q_reg & 0xF000) >> 12

            # Increment ones digit
            ones, carry_out = self.increment_bcd_digit(ones)
            ena_1 = carry_out  # ena_1 is set if overflow from ones

            # Increment tens digit if necessary
            if ena_1:
                tens, carry_out = self.increment_bcd_digit(tens)
                ena_2 = carry_out  # ena_2 is set if overflow from tens

                # Increment hundreds digit if necessary
                if ena_2:
                    hundreds, carry_out = self.increment_bcd_digit(hundreds)
                    ena_3 = carry_out  # ena_3 is set if overflow from hundreds

                    # Increment thousands digit if necessary
                    if ena_3:
                        thousands, _ = self.increment_bcd_digit(thousands)

            # Update the counter
            self.q_reg = (thousands << 12) | (hundreds << 8) | (tens << 4) | ones
            self.ena_reg = (ena_3 << 2) | (ena_2 << 1) | ena_1

