        if signal_vector['reset']:
            self.q_reg = 0x0000
        else:
            self.q_reg = self.increment_counter(self.q_reg)
            self.ena_reg = self.check_enable_signals(self.q_reg)

    def check(self, signal_vector):
        q_observed = signal_vector['q']
        ena_observed = [signal_vector['ena'] >> 1 & 1,
                        signal_vector['ena'] >> 2 & 1,
                        signal_vector['ena'] >> 3 & 1]

        if self.q_reg != q_observed:
            print(f"Scenario: {signal_vector['scenario']}, expected q: {self.q_reg}, observed q: {q_observed}")
            return False

        if self.ena_reg != ena_observed:
            print(f"Scenario: {signal_vector['scenario']}, expected ena: {self.ena_reg}, observed ena: {ena_observed}")
            return False

