        if tens > 9:
            tens = 0
            hundreds += 1
        if hundreds > 9:
            hundreds = 0
            thousands += 1
        if thousands > 9:
            thousands = 0

        return (thousands << 12) | (hundreds << 8) | (tens << 4) | ones

