            ena[0] = 1  # Enable signal for tens increment
        else:
            ena[0] = 0

        if ones == 9 and tens == 9:
            ena[1] = 1  # Enable signal for hundreds increment
        else:
            ena[1] = 0

        if ones == 9 and tens == 9 and hundreds == 9:
            ena[2] = 1  # Enable signal for thousands increment
        else:
