class GoldenDUT:
    def __init__(self):
        # Initialize the internal state variables
        self.q_reg = 0x0000  # 16-bit BCD counter
        self.ena_reg = 0b000  # Enable signals for tens, hundreds, thousands

    def load(self, signal_vector):
        # Load the input signals
        reset = signal_vector['reset']

        # Update internal state based on the input signals
        if reset:
            self.q_reg = 0x0000
            self.ena_reg = 0b000
        else:
            self.q_reg, self.ena_reg = self.bcd_counter(self.q_reg)

    def check(self, signal_vector):
        if signal_vector['check_en']:
            q_observed = signal_vector['q']
            ena_observed = signal_vector['ena']

            if self.q_reg != q_observed:
                print(f"Scenario: {signal_vector['scenario']}, expected: q={hex(self.q_reg)}, observed: q={hex(q_observed)}")
                return False

            if self.ena_reg != ena_observed:
                print(f"Scenario: {signal_vector['scenario']}, expected: ena={bin(self.ena_reg)}, observed: ena={bin(ena_observed)}")
                return False

        return True

    def bcd_counter(self, current_value):
        # Extract each BCD digit
        ones = (current_value >> 0) & 0xF
        tens = (current_value >> 4) & 0xF
        hundreds = (current_value >> 8) & 0xF
        thousands = (current_value >> 12) & 0xF

        # Initialize next variations for the next state
        next_ena = 0b000

        # Increment the ones digit and determine carry-over
        ones += 1
        if ones == 10:
            ones = 0
            tens += 1
            next_ena |= 0b001  # Set tens enable

        # Check and handle the tens digit overflow
        if tens == 10:
            tens = 0
            hundreds += 1
            next_ena |= 0b010  # Set hundreds enable

        # Check and handle the hundreds digit overflow
        if hundreds == 10:
            hundreds = 0
            thousands += 1
            next_ena |= 0b100  # Set thousands enable

        # Reset the thousands digit at overflow
        if thousands == 10:
            thousands = 0

        # Combine digits into next value
        next_q = (thousands << 12) | (hundreds << 8) | (tens << 4) | ones

        return next_q, next_ena
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

