        self.ones_reg = 0
        self.tens_reg = 0
        self.hundreds_reg = 0
        self.thousands_reg = 0
        self.q_reg = 0x0000
        self.ena_reg = [0, 0, 0]

    def load(self, signal_vector):
        if signal_vector['reset']:
            self.q_reg, self.ena_reg = self.reset_bcd()
        else:
            self.q_reg, self.ena_reg = self.bcd_increment(self.q_reg)

    def check(self, signal_vector):
        expected_q = self.q_reg
        expected_ena = self.ena_reg
        q_observed = signal_vector['q']

        if expected_q != q_observed:
            print(f"Scenario: {signal_vector['scenario']}, expected: q={expected_q}, observed q={q_observed}")
            return False

        if 'ena' in signal_vector:
            ena_observed = signal_vector['ena']
            if expected_ena != ena_observed:
                print(f"Scenario: {signal_vector['scenario']}, expected: ena={expected_ena}, observed ena={ena_observed}")
                return False

        return True

    def bcd_increment(self, value):
        if value == 'x':  
            value = 0x0000

        # Unpack BCD digits
        ones = value & 0xF
        tens = (value >> 4) & 0xF
        hundreds = (value >> 8) & 0xF
        thousands = (value >> 12) & 0xF

        # Increment the ones place and handle carryovers
        ena = [0, 0, 0]
        ones += 1

        if ones > 9:
            ones = 0
            tens += 1
            ena[0] = 1

        if tens > 9:
            tens = 0
            hundreds += 1
            ena[1] = 1

        if hundreds > 9:
            hundreds = 0
            thousands += 1
            ena[2] = 1

        if thousands > 9:
            thousands = 0

        # Pack BCD digits back into a single integer
        new_value = (thousands << 12) | (hundreds << 8) | (tens << 4) | ones
        return new_value, ena

